1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Pulsing Circle</title>
7	  <style>
8	    :root {
9	      --circle-hue: #8ec5ff;
10	      --circle-core: #4a7dd9;
11	      --circle-shadow: #1f3a75;
12	      --cycle: 2.5s;
13	    }
14	    * {
15	      margin: 0;
16	      padding: 0;
17	      box-sizing: border-box;
18	    }
19	    body {
20	      width: 100vw;
21	      height: 100vh;
22	      display: flex;
23	      flex-direction: column;
24	      justify-content: center;
25	      align-items: center;
26	      gap: 24px;
27	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
28	      overflow: hidden;
29	    }
30	    svg {
31	      width: min(400px, 80vmin);
32	      height: min(400px, 80vmin);
33	      overflow: visible;
34	      cursor: pointer;
35	      transition: filter 0.3s ease;
36	    }
37	    svg:hover {
38	      filter: brightness(1.08);
39	    }
40	    svg:focus-visible {
41	      outline: 2px solid var(--circle-hue);
42	      outline-offset: 8px;
43	      border-radius: 50%;
44	    }
45	    .ambient {
46	      fill: var(--circle-hue);
47	      opacity: 0.12;
48	      filter: blur(30px);
49	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
50	      transform-origin: 200px 200px;
51	      will-change: transform, opacity;
52	    }
53	    .core {
54	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
55	      transform-origin: 200px 200px;
56	      filter: url(#glow);
57	      will-change: transform, opacity;
58	    }
59	    .highlight {
60	      fill: url(#highlightGradient);
61	      transform-origin: 200px 200px;
62	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
63	      pointer-events: none;
64	      will-change: transform, opacity;
65	    }
66	    .ring {
67	      fill: none;
68	      stroke: var(--circle-hue);
69	      stroke-width: 2.5;
70	      transform-origin: 200px 200px;
71	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
72	      will-change: transform, opacity, stroke-width;
73	    }
74	    .ring--delay-1 {
75	      animation-delay: calc(var(--cycle) / 3);
76	    }
77	    .ring--delay-2 {
78	      animation-delay: calc(var(--cycle) / 3 * 2);
79	    }
80	    @keyframes pulse {
81	      0%, 100% {
82	        transform: scale(1);
83	        opacity: 0.9;
84	      }
85	      50% {
86	        transform: scale(1.05);
87	        opacity: 1;
88	      }
89	    }
90	    @keyframes breathe {
91	      0%, 100% {
92	        transform: scale(0.95);
93	        opacity: 0.1;
94	      }
95	      50% {
96	        transform: scale(1.1);
97	        opacity: 0.18;
98	      }
99	    }
100	    @keyframes ripple {
101	      0% {
102	        transform: scale(1);
103	        opacity: 0.6;
104	        stroke-width: 2.5;
105	      }
106	      100% {
107	        transform: scale(1.35);
108	        opacity: 0;
109	        stroke-width: 0.5;
110	      }
111	    }
112	    @media (prefers-reduced-motion: reduce) {
113	      .core, .ring, .ambient, .highlight {
114	        animation: none;
115	      }
116	      .ring {
117	        opacity: 0.35;
118	      }
119	      .ambient {
120	        opacity: 0.12;
121	      }
122	    }
123	    body.paused .core,
124	    body.paused .ring,
125	    body.paused .ambient,
126	    body.paused .highlight {
127	      animation-play-state: paused;
128	    }
129	    .speed-label {
130	      color: var(--circle-hue);
131	      font-family: system-ui, sans-serif;
132	      font-size: 0.85rem;
133	      letter-spacing: 0.05em;
134	      opacity: 0.7;
135	      user-select: none;
136	      text-align: center;
137	    }
138	    .hint {
139	      display: block;
140	      margin-top: 4px;
141	      font-size: 0.7rem;
142	      opacity: 0.6;
143	    }
144	  </style>
145	</head>
146	<body>
147	  <svg id="ae683f770" viewBox="0 0 400 400" role="button" tabindex="0" aria-label="Pulsing blue circle animation, normal speed. Click or press Enter to change pulse speed. Press space to pause.">
148	    <defs>
149	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
150	        <stop offset="0%" stop-color="#8ec5ff"/>
151	        <stop offset="55%" stop-color="#4a7dd9"/>
152	        <stop offset="100%" stop-color="#1f3a75"/>
153	      </radialGradient>
154	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
155	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
156	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
157	      </radialGradient>
158	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
159	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
160	        <feColorMatrix in="blur" type="matrix"
161	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
162	        <feMerge>
163	          <feMergeNode in="tintedBlur"/>
164	          <feMergeNode in="SourceGraphic"/>
165	        </feMerge>
166	      </filter>
167	    </defs>
168	    <circle class="ambient" cx="200" cy="200" r="160"/>
169	    <circle class="ring" cx="200" cy="200" r="140"/>
170	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
171	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
172	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
173	    <circle class="highlight" cx="200" cy="200" r="140"/>
174	  </svg>
175	  <p class="speed-label" id="speedLabel" aria-live="polite">
176	    Normal speed
177	    <span class="hint">Click to change speed · Space to pause</span>
178	  </p>
179	  <script>
180	    const svg = document.getElementById('ae683f770');
181	    const speedLabel = document.getElementById('speedLabel');
182	    const speeds = [
183	      { value: '2.5s', name: 'Normal speed' },
184	      { value: '1.2s', name: 'Fast speed' },
185	      { value: '4.5s', name: 'Slow speed' },
186	    ];
187	    let speedIndex = 0;
188	    let manuallyPaused = false;
189	
190	    function updateAriaLabel() {
191	      const { name } = speeds[speedIndex];
192	      const state = manuallyPaused ? 'paused' : name.toLowerCase();
193	      svg.setAttribute('aria-label', `Pulsing blue circle animation, ${state}. Click or press Enter to change pulse speed. Press space to pause.`);
194	    }
195	
196	    function cycleSpeed() {
197	      speedIndex = (speedIndex + 1) % speeds.length;
198	      const { value, name } = speeds[speedIndex];
199	      svg.style.setProperty('--cycle', value);
200	      speedLabel.firstChild.textContent = name + ' ';
201	      updateAriaLabel();
202	    }
203	
204	    function togglePause() {
205	      manuallyPaused = !manuallyPaused;
206	      document.body.classList.toggle('paused', manuallyPaused);
207	      updateAriaLabel();
208	    }
209	
210	    svg.addEventListener('click', cycleSpeed);
211	    svg.addEventListener('keydown', (e) => {
212	      if (e.key === 'Enter') {
213	        e.preventDefault();
214	        cycleSpeed();
215	      } else if (e.key === ' ') {
216	        e.preventDefault();
217	        togglePause();
218	      }
219	    });
220	
221	    document.addEventListener('visibilitychange', () => {
222	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
223	    });
224	  </script>
225	</body>
226	</html>
